// CSD_RATIONALE_BEGIN
// Spider text-to-SQL generation should produce exactly one SQL query wrapped in
// a single <<...>> span, with no extra text outside the delimiters. The state
// we track is the full generated output, whether we are currently inside the
// constrained SQL span, and the current constrained substring between the
// delimiters. Outside the span, we aggressively bias generation toward opening
// with "<<" and otherwise allow only one-token progress per step; once the span
// is open, we consult parser validity information to keep the SQL prefix valid.
// Inside the span, we use dead-end detection and valid-candidate queries to
// softly bias logits toward parser-valid continuations, but we only append a
// token when it is actually parser-valid. When the parser reports that the SQL
// prefix is complete, we close the span with ">>" and then stop, ensuring the
// final output remains a single wrapped query.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the outside-span branch, if we force or sample "<<", we
//   set currentConstrainedOut := [], which is a valid prefix by precondition;
//   otherwise we remain outside, so the implication is vacuous. In the
//   complete-prefix branch, CloseConstrainedSpan sets insideConstrainedOut to
//   false, again making the implication vacuous. In the active constrained
//   branch, AppendConstrainedToken is called only after IsTokenValidNext says
//   the chosen token is valid, so the new constrained prefix remains valid; the
//   rejection branch leaves state unchanged.
// suffix: Opening a span appends "<<" to generated and sets
//   currentConstrainedOut := [], so the length-0 suffix matches []. Closing the
//   span uses CloseConstrainedSpan, which appends ">>" and resets the tracked
//   constrained prefix to []. In the constrained append branch,
//   AppendConstrainedToken appends the same token to both generated and
//   currentConstrainedOut; the rejection branch leaves both unchanged.
// cost: The outside-span sampling branch uses raw ChooseNextTokenUnconstrained,
//   so we manually increment helpers.cost once and also increment steps once.
//   CloseConstrainedSpan bumps helpers.cost internally and we increment steps
//   once. In the constrained branch, all query/logit-adjustment helpers are
//   non-bumping; the single raw sample manually bumps helpers.cost once, and
//   steps also increases once. Thus helpers.cost <= steps is preserved.
// progress: In every loop iteration, generated either stays the same or gains
//   exactly one token outside/inside the span, or gains the closing delimiter
//   token via CloseConstrainedSpan; in all cases this is at most one token per
//   iteration. Since steps increases by 1 every iteration, we maintain
//   |generated| <= |generatedPrefix| + steps.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps := 0;
var finished := false;

while steps < maxSteps && !finished
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant insideConstrainedOut ==> generated[|generated| - |currentConstrainedOut|..] == currentConstrainedOut
  invariant |generated| <= |generatedPrefix| + steps
  invariant cost == 0
  invariant helpers.cost <= steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    lm.GenerateLogits(prompt + generated);
    helpers.BoostTokenLogits(lm, ["<<"], 100.0);
    helpers.PenalizeTokenLogits(lm, [">>"], 100.0);
    var next := lm.ChooseNextTokenUnconstrained();
    helpers.cost := helpers.cost + 1;
    steps := steps + 1;

    if next == eosToken {
      finished := true;
    } else if next == "<<" {
      var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
      generated := openedGenerated;
      insideConstrainedOut := openedInside;
      currentConstrainedOut := openedCurrent;
    } else {
      generated := generated + [next];
    }
  } else {
    if parser.IsCompletePrefix(currentConstrainedOut) {
      var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := closedGenerated;
      insideConstrainedOut := closedInside;
      currentConstrainedOut := closedCurrent;
      steps := steps + 1;
      finished := true;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var narrow := helpers.DeadEndDetection(parser, currentConstrainedOut, 1);
      var candidates := helpers.TopValidCandidates(
        lm, parser, constrainedPrompt, currentConstrainedOut, 5, eosToken
      );

      lm.GenerateLogits(constrainedPrompt + currentConstrainedOut);
      if narrow {
        helpers.BoostTokenLogits(lm, candidates, 8.0);
        helpers.PenalizeTokenLogits(lm, ["<<", ">>"], 100.0);
      } else {
        helpers.BoostTokenLogits(lm, candidates, 3.0);
        helpers.PenalizeTokenLogits(lm, ["<<", ">>"], 100.0);
      }

      var next := lm.ChooseNextTokenUnconstrained();
      helpers.cost := helpers.cost + 1;
      steps := steps + 1;

      if next == eosToken {
        finished := true;
      } else {
        var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
        if valid {
          var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := appendedGenerated;
          insideConstrainedOut := appendedInside;
          currentConstrainedOut := appendedCurrent;
        }
      }
    }
  }
}

cost := steps;

